using System.Diagnostics;
using System.IO.Compression;
using System.Security.Cryptography;
using Microsoft.Data.Sqlite;
using OncaPDV.Application;
using OncaPDV.Domain;
using OncaPDV.Infrastructure;
namespace OncaPDV.Tests;
public sealed class OperationalGateTests:IDisposable
{
 private readonly string _root=Path.Combine(Path.GetTempPath(),"onca-gate-"+Guid.NewGuid());private readonly AppPaths _paths;private readonly OncaDatabase _db;private readonly Guid _op=Guid.NewGuid();
 public OperationalGateTests(){_paths=new(_root,Path.Combine(_root,"data"),Path.Combine(_root,"backups"),Path.Combine(_root,"logs"),Path.Combine(_root,"exports"),Path.Combine(_root,"print"));_db=new(_paths);_db.Migrate();}public void Dispose(){SqliteConnection.ClearAllPools();if(Directory.Exists(_root))Directory.Delete(_root,true);}
 [Fact]public async Task Mixed_payment_change_counts_only_allocated_cash(){var product=new Product(Guid.NewGuid(),"MIX",null,"Misto",null,null,null,1,100,5,0,"UN",null,null,true);var products=new SqliteProductRepository(_db);await products.SaveAsync(product);var cart=new Cart();cart.Add(product);var session=await new SqliteCashSessionRepository(_db,new SystemClock()).GetOrOpenAsync(_op);var sale=await new CheckoutService(new SqliteSaleRepository(_db,new SystemClock()),new JsonCartRecoveryStore(_paths)).CompleteAsync(cart,[new(PaymentMethod.Pix,30),new(PaymentMethod.Cash,70,120)],_op,session.Id);Assert.Equal(50,sale.Payments.Sum(x=>x.Change));var summary=await new OperationalService(_db,_paths).SalesSummaryAsync(DateTimeOffset.Now.AddDays(-1),DateTimeOffset.Now.AddDays(1));Assert.Equal(100,summary.Net);Assert.Equal(30,summary.Pix);Assert.Equal(70,summary.Cash);}
 [Fact]public async Task Full_operational_flow_uses_real_services_and_pdfs(){var customers=new CustomerService(new SqliteCustomerRepository(_db));var customer=new CustomerProfile(Guid.NewGuid(),"Cliente E2E",null,null,"11999999999",null,null,null,null,null,null,null,null,null,null,true);await customers.SaveAsync(customer);var product=new Product(Guid.NewGuid(),"E2E",null,"Produto E2E",null,null,null,10,100,10,1,"UN",null,null,true);var products=new SqliteProductRepository(_db);await products.SaveAsync(product);var workflow=new PosWorkflow(products,new JsonCartRecoveryStore(_paths),new SqliteSaleRepository(_db,new SystemClock()),new SqliteCashSessionRepository(_db,new SystemClock()),new SystemClock());await workflow.ScanAsync("E2E");await workflow.SelectCustomerAsync(customer.Id);var sale=await workflow.CompleteAsync([new(PaymentMethod.Pix,30),new(PaymentMethod.Cash,40,60),new(PaymentMethod.StoreCredit,30)],_op);var ops=new OperationalService(_db,_paths);var account=Assert.Single(await ops.CreditsAsync("Open",customer.Id));var session=await new SqliteCashSessionRepository(_db,new SystemClock()).GetOrOpenAsync(_op);var credit=new SqliteCreditRepository(_db,new SystemClock());var partial=await credit.ReceiveAsync(account.Id,10,PaymentMethod.Pix,_op,session.Id,"parcial");var total=await credit.ReceiveAsync(account.Id,20,PaymentMethod.Cash,_op,session.Id,"quitação");var updated=Assert.Single(await ops.CreditsAsync("Paid",customer.Id));Assert.Equal(0,updated.Balance);Assert.True(File.Exists(await ops.SalePdfAsync(sale)));Assert.True(File.Exists(await ops.SalePdfAsync(sale,true)));Assert.True(File.Exists(await ops.CreditPdfAsync(updated,await ops.CreditMovementsAsync(account.Id))));Assert.True(File.Exists(await ops.ReceiptPdfAsync(updated,total)));var report=await ops.SalesSummaryAsync(DateTimeOffset.Now.AddDays(-1),DateTimeOffset.Now.AddDays(1));Assert.True(File.Exists(await ops.SalesReportPdfAsync(report,DateTimeOffset.Now.AddDays(-1),DateTimeOffset.Now.AddDays(1))));var close=await ops.CloseCashAsync(_op,90);Assert.True(File.Exists(await ops.ClosingPdfAsync(close)));var backup=await ops.CreateBackupAsync();await ops.RestoreAsync(backup);Assert.Equal("ok",_db.IntegrityCheck());}
 [Theory][InlineData("truncated")][InlineData("manifest")][InlineData("checksum")][InlineData("missing")]
 public async Task Corrupt_backup_cancels_restore_and_preserves_current_database(string kind){var ops=new OperationalService(_db,_paths);var good=await ops.CreateBackupAsync();var bad=Path.Combine(_paths.Backups,$"bad-{kind}.zip");File.Copy(good,bad);using(var zip=ZipFile.Open(bad,ZipArchiveMode.Update)){if(kind=="missing")zip.GetEntry("database.db")!.Delete();else if(kind=="manifest"){zip.GetEntry("manifest.json")!.Delete();var e=zip.CreateEntry("manifest.json");await using var w=new StreamWriter(e.Open());await w.WriteAsync("{}");}else if(kind=="checksum"){var e=zip.GetEntry("database.db")!;await using var s=e.Open();s.Position=0;s.WriteByte(42);}else{var e=zip.GetEntry("database.db")!;e.Delete();var n=zip.CreateEntry("database.db");await using var s=n.Open();await s.WriteAsync(new byte[]{1,2,3});}}var before=await Hash(_db.DatabasePath);await Assert.ThrowsAnyAsync<Exception>(()=>ops.RestoreAsync(bad));Assert.Equal(before,await Hash(_db.DatabasePath));Assert.Equal("ok",_db.IntegrityCheck());}
 [Fact]public async Task Stock_adjustment_is_audited_and_history_is_visible(){var product=new Product(Guid.NewGuid(),"AJUSTE",null,"Produto Ajuste",null,"Teste",null,3,10,8,2,"UN",null,null,true);var repo=new SqliteProductRepository(_db);await repo.SaveAsync(product);var ops=new OperationalService(_db,_paths);var final=await ops.AdjustStockAsync(product.Id,5,_op,"CONTAGEM FISICA");Assert.Equal(5,final);var saved=await repo.FindAsync("AJUSTE");Assert.Equal(5,saved!.Stock);var movement=Assert.Single(await ops.StockMovementsAsync(product.Id),x=>x.Type=="AJUSTE");Assert.Equal(-3,movement.Quantity);Assert.Contains("CONTAGEM",movement.Reason);await using var c=_db.Open();await using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM audit_log WHERE entity_id=$id AND action='STOCK_ADJUSTMENT'";q.Parameters.AddWithValue("$id",product.Id.ToString());Assert.Equal(1,Convert.ToInt32(await q.ExecuteScalarAsync()));}
 [Fact]public async Task Cash_reopens_with_last_informed_balance_and_lists_closings(){var repo=new SqliteCashSessionRepository(_db,new SystemClock());await repo.GetOrOpenAsync(_op,25);var ops=new OperationalService(_db,_paths);var closed=await ops.CloseCashAsync(_op,37);Assert.Equal(37,closed.Informed);var opened=await ops.OpenCashAsync(_op);Assert.Equal(37,opened.Opening);var history=await ops.CashSessionHistoryAsync(_op);Assert.NotEmpty(history);Assert.Equal(37,history[0].Informed);}
 [Fact]public async Task Detailed_sales_history_filters_and_exports_csv(){var product=new Product(Guid.NewGuid(),"HIST",null,"Produto Historico",null,null,null,1,20,5,0,"UN",null,null,true);var products=new SqliteProductRepository(_db);await products.SaveAsync(product);var workflow=new PosWorkflow(products,new JsonCartRecoveryStore(_paths),new SqliteSaleRepository(_db,new SystemClock()),new SqliteCashSessionRepository(_db,new SystemClock()),new SystemClock());await workflow.ScanAsync("HIST");await workflow.CompleteAsync([new(PaymentMethod.Pix,20)],_op);var ops=new OperationalService(_db,_paths);var rows=await ops.SalesHistoryAsync(DateTimeOffset.Now.AddDays(-1),DateTimeOffset.Now.AddDays(1),"","Pix","Concluidas");var row=Assert.Single(rows);Assert.Equal("CONCLUÍDA",row.Status);var csv=await ops.SalesCsvAsync(rows,DateTimeOffset.Now.AddDays(-1),DateTimeOffset.Now.AddDays(1));Assert.True(File.Exists(csv));Assert.Contains("Produto",await File.ReadAllTextAsync(csv));}
 [Fact]public async Task Users_roles_and_secure_pin_are_enforced(){var security=new PermissionService(_db);await security.EnsureSeedAsync();var admin=await security.AuthenticateAsync("admin","1234");Assert.NotNull(admin);Assert.Equal(UserRole.Admin,admin!.Role);Assert.True(security.Has(admin,AppPermission.CancelCompletedSale));var cashier=new AppUser(Guid.NewGuid(),"caixa1","Caixa 1",UserRole.Caixa,true,false);await security.SaveUserAsync(cashier,"4321");var logged=await security.AuthenticateAsync("caixa1","4321");Assert.NotNull(logged);Assert.True(security.Has(logged!,AppPermission.Sell));Assert.False(security.Has(logged!,AppPermission.AdjustStock));Assert.Null(await security.AuthenticateAsync("caixa1","9999"));}
 [Fact]public async Task Cancel_completed_sale_restores_stock_cash_and_audits(){var p=new Product(Guid.NewGuid(),"CANCEL",null,"Cancelar",null,null,null,5,20,10,0,"UN",null,null,true);var pr=new SqliteProductRepository(_db);await pr.SaveAsync(p);var w=new PosWorkflow(pr,new JsonCartRecoveryStore(_paths),new SqliteSaleRepository(_db,new SystemClock()),new SqliteCashSessionRepository(_db,new SystemClock()),new SystemClock());await w.ScanAsync("CANCEL");await w.ChangeQuantityAsync(p.Id,2);var sale=await w.CompleteAsync([new(PaymentMethod.Cash,40,50)],_op);Assert.Equal(8,(await pr.FindAsync("CANCEL"))!.Stock);var ops=new OperationalService(_db,_paths);await ops.CancelCompletedSaleAsync(sale.Id,_op,"ERRO OPERADOR");Assert.Equal(10,(await pr.FindAsync("CANCEL"))!.Stock);var hist=await ops.SalesHistoryAsync(DateTimeOffset.Now.AddDays(-1),DateTimeOffset.Now.AddDays(1),"","","Todos");Assert.Equal("CANCELADA",Assert.Single(hist).Status);await using var cdb=_db.Open();await using var q=cdb.CreateCommand();q.CommandText="SELECT COUNT(*) FROM cash_movements WHERE origin_id=$id AND type='Sale'";q.Parameters.AddWithValue("$id",sale.Id.ToString());Assert.Equal(0,Convert.ToInt32(await q.ExecuteScalarAsync()));}
 [Fact]public async Task Correct_completed_sale_recalculates_stock_total_and_payment(){var p=new Product(Guid.NewGuid(),"CORR",null,"Corrigir",null,null,null,5,20,10,0,"UN",null,null,true);var pr=new SqliteProductRepository(_db);await pr.SaveAsync(p);var w=new PosWorkflow(pr,new JsonCartRecoveryStore(_paths),new SqliteSaleRepository(_db,new SystemClock()),new SqliteCashSessionRepository(_db,new SystemClock()),new SystemClock());await w.ScanAsync("CORR");await w.ChangeQuantityAsync(p.Id,2);var sale=await w.CompleteAsync([new(PaymentMethod.Pix,40)],_op);var ops=new OperationalService(_db,_paths);var corrected=await ops.CorrectCompletedSaleAsync(sale.Id,_op,new([new(p.Id,p.InternalCode,p.Name,1,25)],0,"QTD LANÇADA ERRADA"));Assert.Equal(25,corrected.Total);Assert.Equal(25,Assert.Single(corrected.Payments).Amount);Assert.Equal(9,(await pr.FindAsync("CORR"))!.Stock);await using var cdb=_db.Open();await using var q=cdb.CreateCommand();q.CommandText="SELECT COUNT(*) FROM sale_corrections WHERE sale_id=$id AND action='CORRECT'";q.Parameters.AddWithValue("$id",sale.Id.ToString());Assert.Equal(1,Convert.ToInt32(await q.ExecuteScalarAsync()));}
 [Fact]public async Task Credit_limit_is_optional_but_enforced_when_configured(){var customer=new CustomerProfile(Guid.NewGuid(),"Limite",null,null,null,null,null,null,null,null,null,null,null,null,null,true);await new CustomerService(new SqliteCustomerRepository(_db)).SaveAsync(customer);var ops=new OperationalService(_db,_paths);await ops.EnsureCreditAvailableAsync(customer.Id,9999);await ops.SetCustomerCreditLimitAsync(customer.Id,50,false,null,_op);await ops.EnsureCreditAvailableAsync(customer.Id,50);await Assert.ThrowsAsync<DomainException>(()=>ops.EnsureCreditAvailableAsync(customer.Id,50.01m));var profile=await ops.CustomerCreditProfileAsync(customer.Id);Assert.Equal(50,profile.Limit);}
 [Fact]public async Task Product_metadata_and_backup_settings_persist(){var productId=Guid.NewGuid();var metadata=new ProductMetadataStore(_db);await metadata.SaveAsync(new(productId,"A-03","Fornecedor XPTO","Etiqueta"));var read=await metadata.LoadAsync(productId);Assert.Equal("A-03",read.Location);var store=new AutomaticBackupSettingsStore(_paths);await store.SaveAsync(new(true,15,Path.Combine(_root,"externo")));var settings=await store.LoadAsync();Assert.True(settings.Enabled);Assert.Equal(15,settings.Retention);Assert.Contains("externo",settings.ExternalFolder);}
 [Fact]public async Task Ten_thousand_customers_have_measured_bounded_searches(){await using(var c=_db.Open()){await using var tx=await c.BeginTransactionAsync();await using var q=c.CreateCommand();q.Transaction=(SqliteTransaction)tx;q.CommandText="INSERT INTO customers(id,name,cpf,cnpj,phone,active) VALUES($id,$name,$cpf,NULL,$phone,1)";var id=q.Parameters.Add("$id",SqliteType.Text);var name=q.Parameters.Add("$name",SqliteType.Text);var cpf=q.Parameters.Add("$cpf",SqliteType.Text);var phone=q.Parameters.Add("$phone",SqliteType.Text);for(var i=0;i<10000;i++){id.Value=Guid.NewGuid().ToString();name.Value=$"CLIENTE CARGA {i:00000}";cpf.Value=$"{i:00000000000}";phone.Value=$"119{i:00000000}";await q.ExecuteNonQueryAsync();}await tx.CommitAsync();}var repo=new SqliteCustomerRepository(_db);async Task<long>Measure(string query){var sw=Stopwatch.StartNew();var result=await repo.SearchAsync(query);sw.Stop();Assert.InRange(result.Count,1,100);return sw.ElapsedMilliseconds;}var opening=await Measure("");var byName=await Measure("CLIENTE CARGA 09999");var byPhone=await Measure("11900009999");var byTax=await Measure("00000009999");Assert.All(new[]{opening,byName,byPhone,byTax},x=>Assert.True(x<5000));Console.WriteLine($"PERF_CLIENTS opening={opening}ms name={byName}ms phone={byPhone}ms tax={byTax}ms");}
 [Fact]public async Task Five_thousand_sales_have_measured_history_report_detail_and_pdf(){var customer=Guid.NewGuid();var session=Guid.NewGuid();var product=Guid.NewGuid();await using(var c=_db.Open()){await using var tx=await c.BeginTransactionAsync();async Task Exec(string sql){await using var q=c.CreateCommand();q.Transaction=(SqliteTransaction)tx;q.CommandText=sql;await q.ExecuteNonQueryAsync();}await Exec($"INSERT INTO customers(id,name,active) VALUES('{customer}','CARGA VENDAS',1)");await Exec($"INSERT INTO products(id,internal_code,name,cost_price,sale_price,stock,minimum_stock,unit,active) VALUES('{product}','LOAD','CARGA',1,10,100000,0,'UN',1)");await Exec($"INSERT INTO cash_sessions(id,operator_id,opened_at,opening_amount) VALUES('{session}','{_op}','{DateTimeOffset.Now.AddDays(-1):O}',0)");for(var i=1;i<=5000;i++){var sale=Guid.NewGuid();var at=DateTimeOffset.Now.AddMinutes(-i);await Exec($"INSERT INTO sales(id,number,created_at,operator_id,customer_id,cash_session_id,discount,total) VALUES('{sale}',{i},'{at:O}','{_op}','{customer}','{session}',0,10)");await Exec($"INSERT INTO sale_items VALUES('{Guid.NewGuid()}','{sale}','{product}','LOAD','CARGA',1,10,10)");await Exec($"INSERT INTO payments VALUES('{Guid.NewGuid()}','{sale}','Pix',10,NULL,0)");}await tx.CommitAsync();}var repo=new SqliteSaleRepository(_db,new SystemClock());var sw=Stopwatch.StartNew();var history=await repo.LastAsync(100);var historyMs=sw.ElapsedMilliseconds;sw.Restart();var detail=await repo.GetAsync(history[0].Id);var detailMs=sw.ElapsedMilliseconds;var ops=new OperationalService(_db,_paths);sw.Restart();var report=await ops.SalesSummaryAsync(DateTimeOffset.Now.AddYears(-1),DateTimeOffset.Now.AddDays(1));var reportMs=sw.ElapsedMilliseconds;sw.Restart();var pdf=await ops.SalesReportPdfAsync(report,DateTimeOffset.Now.AddYears(-1),DateTimeOffset.Now.AddDays(1));var pdfMs=sw.ElapsedMilliseconds;Assert.Equal(5000,report.Quantity);Assert.NotNull(detail);Assert.True(File.Exists(pdf));Assert.All(new[]{historyMs,detailMs,reportMs,pdfMs},x=>Assert.True(x<10000));Console.WriteLine($"PERF_SALES history={historyMs}ms detail={detailMs}ms report={reportMs}ms pdf={pdfMs}ms");}
 private static async Task<string> Hash(string file){await using var s=File.Open(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite);return Convert.ToHexString(await SHA256.HashDataAsync(s));}
}
